Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <cctype>
#include <algorithm>
using namespace std;
const int directions[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int S, T, tot=1, n, tt, inf, b[1000], q[1000000], a[1000000][3], dep[20][20], dis[20][20], p[20][20], s[20][20];
char ma[20][20], mb[20][20];

void add_edge(int x, int y, int c) {
    a[++tot][0] = y; a[tot][1] = c; a[tot][2] = b[x]; b[x] = tot;
    a[++tot][0] = x; a[tot][1] = 0; a[tot][2] = b[y]; b[y] = tot;
}

void bfs(int x0, int y0, bool flag) {
    int l=1, r=1, id=p[x0][y0];
    q[l] = x0*1000 + y0;
    memset(dis, 63, sizeof(dis));
    inf = dis[0][0];
    dis[x0][y0] = 0;
    while (l <= r) {
        int x = q[l]/1000, y = q[l]%1000; l++;
        if (flag && s[x][y]!=0 && dis[x][y]<=tt && dis[x][y]<=dep[x][y])
            add_edge(id, s[x][y], inf);
        if (dis[x][y]>tt || dis[x][y]>=dep[x][y]) continue;
        if (id==3 && s[x][y]==9) cout << dis[x][y] << endl;
        for (int i=0; i<4; i++) {
            int nx=x+directions[i][0], ny=y+directions[i][1];
            if (nx>0 && nx<=n && ny>0 && ny<=n && isdigit(ma[nx][ny]) && dis[nx][ny]==inf) {
                dis[nx][ny]=dis[x][y]+1;
                q[++r]=nx*1000+ny;
            }
        }
    }
}

int d[1000];

bool build() {
    memset(d, 0, sizeof(d));
    int l=1, r=1; q[l]=S; d[S]=1;
    while (l<=r) {
        int x=q[l++]; 
        for (int i=b[x]; i; i=a[i][2]) {
            int y=a[i][0];
            if (d[y] || !a[i][1]) continue;
            d[y]=d[x]+1; q[++r]=y;
            if (y==T) return true;
        }
    }
    return false;
}

int dinic(int x, int flow) {
    if (x==T) return flow;
    int k=flow;
    for (int i=b[x]; i; i=a[i][2]) {
        int y=a[i][0];
        if (d[y]!=d[x]+1 || !a[i][1]) continue;
        int t=dinic(y, min(k, a[i][1]));
        k-=t; a[i][1]-=t; a[i^1][1]+=t;
        if (k==0) return flow;
    }
    if (k==flow) d[x]=-1;
    return flow - k;
}

int main() {
    cin >> n >> tt;
    for (int i=1; i<=n; i++) cin >> ma[i]+1;
    for (int i=1; i<=n; i++) cin >> mb[i]+1;
    memset(dep, 63, sizeof(dep));
    for (int i=1; i<=n; i++)
        for (int j=1; j<=n; j++)
            if (ma[i][j]=='Z') bfs(i,j,false);
    memcpy(dep, dis, sizeof(dis));
    int t=1;
    S=0; T=1;
    for (int i=1; i<=n; i++)
        for (int j=1; j<=n; j++) {
            if (ma[i][j]>'0' && ma[i][j]<='9') {
                p[i][j]=++t;
                add_edge(S, t, ma[i][j]-'0');
            }
            if (mb[i][j]>'0' && mb[i][j]<='9') {
                s[i][j]=++t;
                add_edge(t, T, mb[i][j]-'0');
            }
        }
    for (int i=1; i<=n; i++)
        for (int j=1; j<=n; j++)
            if (p[i][j]) bfs(i,j,true);
    int ans=0;
    while (build()) ans+=dinic(S, inf);
    cout << ans << endl;
    return 0;
}
